class Poly:
 def __init__(self,d): self.d={k:F(v) for k,v in d.items() if v}
 def __add__(self,o):
  if not isinstance(o,Poly):o=Poly({(0,0):o})
  d=self.d.copy()
  for k,v in o.d.items():d[k]=d.get(k,0)+v
  return Poly(d)
 __radd__=__add__
 def __neg__(self):return Poly({k:-v for k,v in self.d.items()})
 def __sub__(self,o):return self+-o
 def __rsub__(self,o):return -self+o
 def __mul__(self,o):
  if not isinstance(o,Poly):o=Poly({(0,0):o})
  d={}
  for (i,j),a in self.d.items():
   for (k,l),b in o.d.items(): d[i+k,j+l]=d.get((i+k,j+l),0)+a*b
  return Poly(d)
 __rmul__=__mul__
 def __pow__(self,n):
  p=Poly({(0,0):1})
  for _ in range(n):p=p*self
  return p
